sys_script.script:
(function executeRule(current, previous) {
    var supplierId = current.getValue('supplier');
    var materialId = current.getValue('material_product');
    var isActive = current.getValue('active');
    var isPreferred = current.getValue('preferred');

    if (!supplierId || !materialId) {
        return;
    }

    // ─────────────────────────────────────────────
    // CHECK 1: Prevent duplicate active supplier-material profiles.
    //
    // The database unique index on (supplier, material_product) prevents
    // any duplicate regardless of active flag. This check provides a
    // user-friendly message specifically for the active-duplicate case.
    // ─────────────────────────────────────────────
    if (isActive == '1' || isActive == 'true' || isActive === true) {
        var dup = new GlideRecord('x_2056099_indust_0_supp_mat');
        dup.addQuery('supplier', supplierId);
        dup.addQuery('material_product', materialId);
        dup.addQuery('active', true);

        // Exclude self (important for updates)
        var selfId = current.getUniqueValue();
        if (selfId) {
            dup.addQuery('sys_id', '!=', selfId);
        }

        dup.setLimit(1);
        dup.query();

        if (dup.hasNext()) {
            var suppName = current.getDisplayValue('supplier') || supplierId;
            var matName = current.getDisplayValue('material_product') || materialId;
            gs.addErrorMessage(
                'Duplicate supplier-material profile: An active profile for supplier "' +
                suppName + '" and material "' + matName +
                '" already exists. Deactivate the existing profile before creating a new one.'
            );
            current.setAbortAction(true);
            return;
        }
    }

    // ─────────────────────────────────────────────
    // CHECK 2: Ensure only one preferred supplier per material.
    //
    // If this profile is being marked as preferred AND active,
    // clear the preferred flag on any other active profile for
    // the same material. This ensures exactly one preferred
    // supplier per material at any time.
    // ─────────────────────────────────────────────
    if ((isPreferred == '1' || isPreferred == 'true' || isPreferred === true) &&
        (isActive == '1' || isActive == 'true' || isActive === true)) {

        var others = new GlideRecord('x_2056099_indust_0_supp_mat');
        others.addQuery('material_product', materialId);
        others.addQuery('preferred', true);
        others.addQuery('active', true);

        var selfId2 = current.getUniqueValue();
        if (selfId2) {
            others.addQuery('sys_id', '!=', selfId2);
        }

        others.query();

        while (others.next()) {
            others.setValue('preferred', false);
            others.setWorkflow(false); // Avoid triggering other BRs during cleanup
            others.update();
        }
    }
})(current, previous);
